## בדיקת מספר ראשוני
### פונקציה
```javascript
/**
 * בודקת אם מספר הוא ראשוני.
 * 
 * @param {number} num - המספר לבדיקה.
 * @returns {boolean} - true אם המספר הוא ראשוני, false אחרת.
 */
function isPrime(num) {
  // מספרים קטנים מ-2 אינם ראשוניים
  if (num < 2) {
    return false;
  }

  // 2 הוא המספר הראשוני היחיד
  if (num === 2) {
    return true;
  }

  // מספרים זוגיים (פרט ל-2) אינם ראשוניים
  if (num % 2 === 0) {
    return false;
  }

  // בדיקה עד השורש הריבועי של המספר
  for (let i = 3; i * i <= num; i += 2) {
    // אם המספר מתחלק ב-i, הוא אינו ראשוני
    if (num % i === 0) {
      return false;
    }
  }

  // אם המספר עבר את כל הבדיקות, הוא ראשוני
  return true;
}
```

### דוגמאות
```javascript
console.log(isPrime(25)); // false
console.log(isPrime(23)); // true
console.log(isPrime(37)); // true
console.log(isPrime(48)); // false
```

### הסבר
הפונקציה `isPrime` בודקת אם מספר הוא ראשוני. היא עוברת דרך מספר תנאים:

*   מספרים קטנים מ-2 אינם ראשוניים.
*   2 הוא המספר הראשוני היחיד.
*   מספרים זוגיים (פרט ל-2) אינם ראשוניים.
*   הפונקציה בודקת עד השורש הריבועי של המספר, ואם המספר מתחלק באחד מהמספרים בטווח זה, הוא אינו ראשוני.

אם המספר עובר את כל הבדיקות, הפונקציה מחזירה `true`, ואחרת היא מחזירה `false`.
